// Parse and validate input (API v2 - segment_id replaces source_text_id + segment_index)
const input = $input.first().json;
const body = input.body || input;

if (!body.translation && !body.translated_text) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_TRANSLATION', message: 'translation or translated_text is required' }
    }
  }];
}

// API v2: exactly one of segment_id, commentary_id, or source_text must be provided
const hasSegmentId = !!body.segment_id;
const hasCommentaryId = !!body.commentary_id;
const hasSourceText = !!body.source_text;

if (!hasSegmentId && !hasCommentaryId && !hasSourceText) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_ID', message: 'One of segment_id, commentary_id, or source_text is required (API v2)' }
    }
  }];
}

return [{
  json: {
    jobId: body.job_id,
    translation: body.translation || body.translated_text,
    segmentId: body.segment_id || null,
    commentaryId: body.commentary_id || null,
    sourceText: body.source_text || null,
    targetLanguage: body.target_language || 'fr',
    provider: body.provider || 'anthropic',
    model: body.model || 'claude-sonnet-4-20250514',
    qualityScore: body.quality_score || null,
    confidenceScore: body.confidence_score || null,
    requestId: body.request_id || null,
    llmUsage: body.llm_usage || null,
    status: body.status || 'approved',
    notes: body.notes || null,
    issues: body.issues || [],
    extraData: body.extra_data || {}
  }
}];

// Format response (API v2)
const input = $input.first().json;

if (input.error) {
  return [{
    json: {
      success: false,
      error: {
        code: 'SAVE_ERROR',
        message: input.error.message || input.detail?.message || 'Failed to save translation'
      }
    }
  }];
}

// API v2 response format
return [{
  json: {
    success: input.success !== false,
    mode: input.mode || 'segment',
    translation_id: input.translation_id,
    segment_id: input.segment_id || null,
    commentary_id: input.commentary_id || null,
    target_language: input.target_language,
    version: input.version || 1,
    status: input.status || 'approved',
    created_at: input.created_at,
    message: input.message || 'Translation saved'
  }
}];

